@Entity
public class Employee {
    @Id private Long id;
    private String name;
    private Long managerId; // references another Employee.id
}

// Native SQL query in repository
@Query(value = """
    SELECT e.name AS employee_name, m.name AS manager_name
    FROM employee e
    LEFT JOIN employee m ON e.manager_id = m.id
    WHERE e.department = :dept
    """, nativeQuery = true)
List<Object[]> findEmployeesWithManagers(String dept);

// Usage in service
var results = employeeRepository.findEmployeesWithManagers("Engineering");
for (var row : results) {
    var empName = (String) row[0];
    var mgrName = (String) row[1]; // NULL if no manager
    System.out.println(empName + " reports to " + mgrName);
}

@Entity
class ProductSize {
    @Id private Long id;
    private String size; // S, M, L, XL
}

@Entity
class ProductColor {
    @Id private Long id;
    private String color; // Red, Blue, Green
}

// Generate all size-color combinations for inventory setup
@Query(value = """
    SELECT s.size, c.color
    FROM product_size s
    CROSS JOIN product_color c
    ORDER BY s.size, c.color
    """, nativeQuery = true)
List<Object[]> generateProductVariants();

// Service usage
var variants = productRepository.generateProductVariants();
// Result: (S, Red), (S, Blue), (S, Green), (M, Red), (M, Blue), ...
for (var v : variants) {
    var sku = "TSHIRT-" + v[0] + "-" + v[1];
    inventoryService.createSku(sku); // Create all 12 SKUs (4 sizes × 3 colors)
}

@Entity
class Order {
    @Id private Long id;
    @ManyToOne(fetch = FetchType.LAZY) // default: lazy loading
    private Customer customer;
}

// BAD: N+1 problem
var orders = orderRepository.findAll(); // 1 query
for (var order : orders) {
    var name = order.getCustomer().getName(); // N queries fired here
    System.out.println("Order by " + name);
}

// GOOD: JOIN FETCH eliminates N+1
@Query("SELECT o FROM Order o JOIN FETCH o.customer WHERE o.status = :status")
List<Order> findOrdersWithCustomer(String status);

var orders = orderRepository.findOrdersWithCustomer("COMPLETED"); // 1 query with JOIN
for (var order : orders) {
    var name = order.getCustomer().getName(); // no additional query
    System.out.println("Order by " + name);
}

// Entities
@Entity
class Customer {
    @Id private Long id;
    private String name;
}

@Entity
class Order {
    @Id private Long id;
    private Long customerId; // may be orphaned (customer deleted)
}

// Native query: find all customers and orders, including unmatched
@Query(value = """
    SELECT c.id AS customer_id, c.name, o.id AS order_id
    FROM customer c
    LEFT JOIN orders o ON c.id = o.customer_id
    UNION
    SELECT c.id AS customer_id, c.name, o.id AS order_id
    FROM customer c
    RIGHT JOIN orders o ON c.id = o.customer_id
    """, nativeQuery = true)
List<Object[]> findCustomersAndOrdersFullOuter();

// Result includes: customers without orders (order_id NULL),
// orders without customers (customer_id NULL), and matched pairs
